def test_the_last_object_wins_over_one_quoted_earlier():
    for rid, earlier in (("last_json_wins", "quotes the rubric's format example"),
                         ("nested_object", "shows a draft verdict, and the answer nests an object of its own")):
        r = row(rid)
        got = read(r["reply"])
        assert got == tuple(r["expect"]), (
            f"{rid}: the reply {earlier}: {r['reply'][:110]!r}...; p1_verdict returned {got!r}, the answer is "
            f"{tuple(r['expect'])!r}. The rubric's Verdict format: the answer is the last JSON object in the reply; "
            f"an object nested inside it is part of it, not a later one."
        )

def test_a_missing_null_or_non_text_explanation_reads_empty():
    for rid in ("no_explanation", "null_explanation", "list_explanation"):
        r = row(rid)
        got = read(r["reply"])
        assert got == tuple(r["expect"]), (
            f"{rid}: {r['reply']!r} has a verdict and no usable explanation; p1_verdict returned {got!r}, expected "
            f"{tuple(r['expect'])!r}. The reason is stored as text in judge_verdict.reason (NOT NULL): an explanation "
            f"that is missing, null or not a string is \"\", not None, not the string 'None' and not a list."
        )

def test_the_prefix_is_never_doubled():
    for rid in ("unknown_prefixed", "unknown_tight_prefix", "fail_unknown_kept"):
        r = row(rid)
        got = read(r["reply"])
        assert got == tuple(r["expect"]), (
            f"{rid}: the judge answered {r['reply'].splitlines()[-1]!r}; p1_verdict returned {got!r}, expected "
            f"{tuple(r['expect'])!r}. An explanation that already starts with 'unknown:' keeps one prefix, and a fail "
            f"the judge wrote that way is already an abstain."
        )

def test_every_abstain_is_one_journal_abstained_counts():
    for rid in ("unknown_becomes_fail", "unknown_prefixed", "unknown_tight_prefix", "unknown_capital_prefix",
                "unknown_bare", "fail_unknown_kept"):
        got = read(row(rid)["reply"])
        stored = {"verdict": got[0], "reason": got[1]} if isinstance(got, tuple) else None
        assert stored is not None and journal.abstained(stored), (
            f"{rid}: p1_verdict returned {got!r}; journal.abstained, which `tr label agree` uses to leave unknowns "
            f"out of kappa, does not count it as an abstain (it wants verdict 'fail', reason starting 'unknown:' in "
            f"lower case)."
        )

def test_only_the_three_lower_case_verdicts_count():
    for rid in ("maybe", "capitalised", "null_verdict", "padded_verdict", "hedged", "list_verdict"):
        r = row(rid)
        got = read(r["reply"])
        assert isinstance(got, CannotGrade), (
            f"{rid}: {r['reply'].splitlines()[-1]!r}; p1_verdict returned {shown(got)}. The rubric asks for exactly "
            f"the string pass or fail (or unknown), in lower case, nothing around it; anything else is a reply the "
            f"rubric does not define, so CannotGrade, not a guess at what the judge meant."
        )

@pytest.mark.parametrize("cap, sends", [(0.0435, True), (0.0425, False), (0.04297, True), (0.04296, False)])
def test_the_cap_is_the_callers_to_a_thousandth_of_a_cent(cap, sends, tmp_path):
    got, sent, _ = fakea.judge(tmp_path, max_usd=cap)
    assert bool(sent) == sends, (
        f"With max_usd={cap}, just {'above' if sends else 'below'} one call's worst case as the budget estimates it "
        f"(${WORST_CASE}), p1_judge sent {len(sent)} request(s) and ended with {fakea.shown(got)}; it should "
        f"{'send its one call' if sends else 'refuse before sending'}. The cap is the money the caller allows, as "
        f"given: tr grade passes what is left of its own budget, so a margin, a rounding or extra slack on top moves "
        f"the line the caller drew."
    )

@pytest.mark.parametrize("broken", ["add_judge_verdict", "_insert_score"])
def test_a_failure_between_the_two_writes_leaves_neither(tmp_path, broken):
    j = fakea.judging(tmp_path, broken=broken)
    assert isinstance(j.got, sqlite3.OperationalError), (
        f"With journal.{broken} failing, p1_judge ended with {fakea.shown(j.got)}; the storage error should reach the "
        f"caller."
    )
    row, scores = fakea.stored(j.conn, j.thesis.thesis_id)
    assert row is None and not scores, (
        f"journal.{broken} failed (injected) and the journal still holds {held(row, scores)}. The verdict and the "
        f"ScoreRecord it points at land in one transaction: a failure between the two writes leaves neither."
    )

